// Single source of settings for this workflow. The build injects
// config/config.local.json here and nowhere else.
// @inject config as CONFIG
// @end-inject
return [{ json: CONFIG }];

// One Telegram message per failed execution. Error Trigger payload:
// { execution: { id, url, error: { message }, lastNodeExecuted, mode }, workflow: { id, name } }
// or, for a failing trigger node: { trigger: { error: { message }, mode }, workflow }.
const CONFIG = $('Config').first().json;
const d = $('Error Trigger').first().json;
const ru = CONFIG.language.digest === 'ru';
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const wf = d.workflow || {};
const ex = d.execution || {};
const err = ex.error || d.trigger?.error || {};
const nodeName = ex.lastNodeExecuted || (d.trigger ? 'trigger' : null);
const when = $now.setZone(CONFIG.timezone).toFormat('yyyy-LL-dd HH:mm');
const lines = [
  '\u26a0\ufe0f <b>' + esc(wf.name || 'n8n') + '</b>',
  nodeName ? (ru ? 'Узел: ' : 'Node: ') + esc(nodeName) : '',
  (ru ? 'Ошибка: ' : 'Error: ') + esc(err.message || (ru ? 'без описания' : 'no message')),
  ex.url ? (ru ? 'Запуск: ' : 'Execution: ') + esc(ex.url) : '',
  (ru ? 'Время: ' : 'Time: ') + when,
].filter(Boolean);
let text = lines.join('\n');
if (text.length > 3500) text = text.slice(0, 3499) + '…';
return [{ json: { text } }];
